import java.io.*;
import java.math.BigInteger;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int rows = fs.nextInt();
        int cols = fs.nextInt();
        int[][] grid = new int[rows][cols];
        BigInteger[] rhs = new BigInteger[rows + cols];
        int[][] coefficient = new int[rows + cols][676];
        boolean[] present = new boolean[676];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                String name = fs.next();
                int id = (name.charAt(0) - 'a') * 26 + name.charAt(1) - 'a';
                grid[r][c] = id;
                present[id] = true;
                coefficient[r][id]++;
            }
            rhs[r] = new BigInteger(fs.next());
        }

        for (int c = 0; c < cols; c++) {
            rhs[rows + c] = new BigInteger(fs.next());
            for (int r = 0; r < rows; r++) {
                coefficient[rows + c][grid[r][c]]++;
            }
        }

        int equationCount = rows + cols;
        int[] unknownCount = new int[equationCount];
        ArrayDeque<Integer> queue = new ArrayDeque<>();

        for (int e = 0; e < equationCount; e++) {
            for (int v = 0; v < 676; v++) {
                if (coefficient[e][v] > 0) unknownCount[e]++;
            }
            if (unknownCount[e] == 1) queue.add(e);
        }

        BigInteger[] value = new BigInteger[676];
        while (!queue.isEmpty()) {
            int e = queue.remove();
            if (unknownCount[e] != 1) continue;

            int variable = -1;
            for (int v = 0; v < 676; v++) {
                if (coefficient[e][v] > 0 && value[v] == null) {
                    variable = v;
                    break;
                }
            }
            if (variable == -1) continue;

            BigInteger[] division = rhs[e].divideAndRemainder(
                    BigInteger.valueOf(coefficient[e][variable]));
            value[variable] = division[0];

            for (int other = 0; other < equationCount; other++) {
                int count = coefficient[other][variable];
                if (count > 0) {
                    rhs[other] = rhs[other].subtract(
                            value[variable].multiply(BigInteger.valueOf(count)));
                    unknownCount[other]--;
                    if (unknownCount[other] == 1) queue.add(other);
                }
            }
        }

        StringBuilder out = new StringBuilder();
        for (int v = 0; v < 676; v++) {
            if (present[v]) {
                out.append((char) ('a' + v / 26))
                   .append((char) ('a' + v % 26))
                   .append(' ')
                   .append(value[v])
                   .append('\n');
            }
        }
        System.out.print(out);
    }
}
